package it.polimi.ingsw.am14.network.messages.events;
/**
 * Abstract superclass representing an event generated by the server.
 * Inherits from {@link Event}.
 * Subclasses of this class are used to communicate specific server-side occurrences
 * or state changes to the clients.
 */
public abstract class ServerEvent extends Event{
    /**
     * Constructs a {@code ServerEvent} with the specified description.
     *
     * @param description a brief explanation or message detailing the event.
     */

    public ServerEvent(String description) {
        super(description);
    }

}
